sys_ws_operation.operation_script:
(function process( /*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    try {
        var enable_logging = gs.getProperty('x_hsb11_swb_hndlr.swb_authz_api_enable_logging', 'false') === 'true';

        //get search parameters
        var object_id_type = request.body.data.object_id_type;
        var object_id = request.body.data.object_id;
        var employee_number = request.body.data.user_id;
        var queue_name = request.body.data.queue_name;
        var auth = false;

        //Validate user with employee number
        try {
            var gr_usr = new GlideRecord('sys_user');
            gr_usr.addQuery("employee_number", employee_number);
            gr_usr.query();
            if (gr_usr.next()) {
                //compare maker with request details
                var gr_ect = new GlideRecord('x_hsb11_hsbcmss_eh_hsbc_email_case_task');
                gr_ect.addQuery('maker', gr_usr.sys_id);
                gr_ect.addQuery('swb_id', object_id);
                gr_ect.addQuery('queue_name', queue_name);
                gr_ect.query();
                if (gr_ect.next()) {
                    auth = true;
                }
            }
        } catch (error) {
            gs.error('SWB AuthZ APIs- Error while checking the user id details: ' + employee_number + ' Error: ' + error.message);
        }
        //MSSOTIQUBE-1148 - Added logs
        if (enable_logging)
            gs.info('SWB AuthZ APIs - Is authorized: ' + auth);

        var result = {
            "authorized": auth
        };
        response.setContentType('application/json');
        response.setStatus(200);
        response.setBody(result);
    } catch (error) {
        gs.error('SWB AuthZ APIs- Error executing verify user auth script : ' + error.message);
    }
})(request, response);
